# spi_adc_functions.py
# Reads data from an MCP3208 ADC using different functional styles.

import spidev
import time

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
MAX_CHANNEL = 7
MAX_VALUE = 4095

def validate_channel(channel):
    """Validates the ADC channel number."""
    if not 0 <= channel <= MAX_CHANNEL:
        raise ValueError(f"Invalid channel: {channel}. Must be 0-{MAX_CHANNEL}.")

def init_spi():
    """Initializes the SPI connection."""
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = 1000000  # 1 MHz
        spi.mode = 0b00  # Mode 0
        return spi
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return None

def read_raw(spi, channel):
    """Reads raw data from the MCP3208."""
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        print(f"Error reading from ADC channel {channel}: {e}")
        return None

def read_percentage(spi, channel):
    """Reads data and returns a percentage."""
    raw_data = read_raw(spi, channel)
    if raw_data is None:
        return None
    percentage = round((raw_data / MAX_VALUE) * 100, 2)
    return percentage

def read_voltage(spi, channel, vref=3.3):
    """Reads data and returns a voltage."""
    raw_data = read_raw(spi, channel)
    if raw_data is None:
        return None
    voltage = round((raw_data / MAX_VALUE) * vref, 2)
    return voltage

def read_adc_channel(channel, read_function):
    """Generic function to read ADC data."""
    try:
        validate_channel(channel)
        spi = init_spi()
        if spi is None:
            return None
        result = read_function(spi, channel)
        spi.close()
        return result
    except ValueError as e:
        print(e)
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

def main():
    """Main function to demonstrate ADC reading."""
    try:
        percentage = read_adc_channel(0, read_percentage)
        if percentage is not None:
            print(f"Channel 0: {percentage}%")

        voltage = read_adc_channel(0, read_voltage)
        if voltage is not None:
            print(f"Channel 0: {voltage}V")

        raw_value = read_adc_channel(0, read_raw)
        if raw_value is not None:
            print(f"Channel 0: {raw_value}")

    except Exception as e:
        print(f"An error occurred in main: {e}")

if __name__ == "__main__":
    main()

