import smbus
import time

bus = smbus.SMBus(1)
addr = 0x48
config = [0x83, 0xE0]

def readAdc(c):
    v = bus.read_i2c_block_data(addr, config[c], 2)
    return ((v[0] << 8) | v[1]) * 16 >> 16

try:
    while True:
        for i in range(4):
            print(f"ADC {i}: {readAdc(i)}")
        time.sleep(0.05)
except:
    pass

