import RPi.GPIO as GPIO
import spidev
import time
import datetime
import os
import signal
import sys
import json
import urllib.request
import urllib.error

# Configuration
DHT_PIN = 4
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25
SPI_CE = 8
SPI_MOSI = 10
SPI_MISO = 9
SPI_SCLK = 11
ADC_CHANNEL = 0
SERVER_URL = "http://your-server-url.com/api/greenhouse"
WATCHDOG_TIMEOUT = 600  # 10 minutes in seconds
RETRY_DELAY = 5  # seconds
MAX_RETRIES = 3

# Global variables
last_loop_time = time.time()
spi = None  # SPI object

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(PUMP_PIN, GPIO.OUT)
GPIO.setup(FAN_PIN, GPIO.OUT)
GPIO.setup(LIGHT_PIN, GPIO.OUT)
GPIO.setup(LED_PIN, GPIO.OUT)

# Initialize SPI
try:
    spi = spidev.SpiDev()
    spi.open(0, 0)  # CE0
    spi.max_speed_hz = 1000000
except Exception as e:
    print(f"Error initializing SPI: {e}")
    sys.exit(1)

# Function to read data from DHT22 sensor
def read_dht22():
    try:
        import dht
        sensor = dht.DHT22(DHT_PIN)
        result = sensor.read()
        if result.is_valid():
            temperature = result.temperature
            humidity = result.humidity
            return temperature, humidity
        else:
            log_message(f"DHT22 sensor reading failed: {result.error_code}")
            return None, None
    except Exception as e:
        log_message(f"Error reading DHT22 sensor: {e}")
        return None, None

# Function to read analog value from MCP3008 ADC
def read_adc(channel):
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        log_message(f"Error reading ADC channel {channel}: {e}")
        return None

# Function to control the pump
def control_pump(command):
    try:
        if command == "on":
            GPIO.output(PUMP_PIN, GPIO.HIGH)
            log_message("Pump turned ON")
        elif command == "off":
            GPIO.output(PUMP_PIN, GPIO.LOW)
            log_message("Pump turned OFF")
        else:
            log_message(f"Invalid pump command: {command}")
    except Exception as e:
        log_message(f"Error controlling pump: {e}")

# Function to control the fan
def control_fan(command):
    try:
        if command == "on":
            GPIO.output(FAN_PIN, GPIO.HIGH)
            log_message("Fan turned ON")
        elif command == "off":
            GPIO.output(FAN_PIN, GPIO.LOW)
            log_message("Fan turned OFF")
        else:
            log_message(f"Invalid fan command: {command}")
    except Exception as e:
        log_message(f"Error controlling fan: {e}")

# Function to control the light
def control_light(command):
    try:
        if command == "on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            log_message("Light turned ON")
        elif command == "off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            log_message("Light turned OFF")
        else:
            log_message(f"Invalid light command: {command}")
    except Exception as e:
        log_message(f"Error controlling light: {e}")

# Function to set the LED status
def set_led_status(mode):
    try:
        if mode == "online":
            GPIO.output(LED_PIN, GPIO.HIGH)
        elif mode == "offline":
            GPIO.output(LED_PIN, GPIO.LOW)
        elif mode == "error":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        elif mode == "synchronizing":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        else:
            log_message(f"Invalid LED mode: {mode}")
    except Exception as e:
        log_message(f"Error setting LED status: {e}")

# Function to log messages to file
def log_message(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - {message}\n"
    try:
        with open("greenhouse.log", "a") as f:
            f.write(log_entry)
    except Exception as e:
        print(f"Error writing to log file: {e}")

# Function to send data to the server
def send_data(data):
    try:
        data_json = json.dumps(data).encode('utf-8')
        req = urllib.request.Request(SERVER_URL, data=data_json, headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.getcode() == 200:
                log_message("Data sent successfully")
                return True
            else:
                log_message(f"Server returned error code: {response.getcode()}")
                return False
    except urllib.error.URLError as e:
        log_message(f"Network error: {e}")
        return False
    except Exception as e:
        log_message(f"Error sending data: {e}")
        return False

# Function to receive commands from the server
def receive_commands():
    try:
        req = urllib.request.Request(SERVER_URL, headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.getcode() == 200:
                data = json.loads(response.read().decode('utf-8'))
                log_message("Commands received successfully")
                return data
            else:
                log_message(f"Server returned error code: {response.getcode()}")
                return None
    except urllib.error.URLError as e:
        log_message(f"Network error: {e}")
        return None
    except Exception as e:
        log_message(f"Error receiving commands: {e}")
        return None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    log_message("Shutting down gracefully...")
    set_led_status("offline")
    GPIO.cleanup()
    if spi:
        spi.close()
    sys.exit(0)

# Main loop
def main():
    global last_loop_time
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    set_led_status("offline")  # Initially offline

    while True:
        try:
            # Read sensor data
            temperature, humidity = read_dht22()
            soil_moisture = read_adc(ADC_CHANNEL)

            if temperature is not None and humidity is not None and soil_moisture is not None:
                # Prepare data for sending
                data = {
                    "temperature": temperature,
                    "humidity": humidity,
                    "soil_moisture": soil_moisture
                }

                # Send data to server
                if send_data(data):
                    set_led_status("online")
                else:
                    set_led_status("offline")
            else:
                log_message("Failed to read sensor data. Skipping data sending.")
                set_led_status("offline")

            # Receive commands from server
            commands = receive_commands()
            if commands:
                if "pump" in commands:
                    control_pump(commands["pump"])
                if "fan" in commands:
                    control_fan(commands["fan"])
                if "light" in commands:
                    control_light(commands["light"])

            # Watchdog timer
            current_time = time.time()
            if current_time - last_loop_time > WATCHDOG_TIMEOUT:
                log_message("Watchdog timeout! Restarting process...")
                os.execv(sys.executable, ['python'] + sys.argv)  # Restart the script
            last_loop_time = current_time

            time.sleep(300)  # Wait 5 minutes

        except Exception as e:
            log_message(f"An unexpected error occurred: {e}")
            set_led_status("error")
            time.sleep(60)  # Wait before retrying

if __name__ == "__main__":
    main()

