import time
import cv2
import numpy as np

# Initialize camera
try:
    camera = cv2.VideoCapture(0)
    time.sleep(2)  # Warm-up
except:
    exit()

baseline = None
while True:
    try:
        ret, frame = camera.read()
        if not ret:
            break
        avg = np.mean(frame)
        if baseline is None or abs(avg - baseline) > 10:
            cv2.imwrite("motion.jpg", frame)
            baseline = avg
        time.sleep(2)
    except:
        break
camera.release()

