import cv2,sys,time,config,face,hardware
from picamera import PiCamera
from picamera.array import PiRGBArray
cam=PiCamera()
cam.resolution=config.RESOLUTION
cam.rotation=config.ROTATION
raw=PiRGBArray(cam,size=config.RESOLUTION)
face_cascade=cv2.CascadeClassifier(config.CASCADE_FILE)
rec=cv2.face.EigenFaceRecognizer_create()
rec.read(config.TRAINING_FILE)
box=hardware.Box()
box.lock()
while 1:
    try:
        if box.is_button_up():
            if box.is_locked:
                img=box.capture()
                gray=cv2.cvtColor(img,cv2.COLOR_BGR2GRAY)
                faces=face_cascade.detectMultiScale(gray,1.3,5)
                if len(faces)==1:
                    x,y,w,h=faces[0]
                    cropped=face.crop(gray,x,y,w,h)
                    resized=face.resize(cropped)
                    l,conf=rec.predict(resized)
                    if l==config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD>conf>1500:
                        box.unlock()
            else:box.lock()
        time.sleep(0.1)
    except KeyboardInterrupt:sys.exit()
    except:box.lock();time.sleep(0.1)

