import io
import logging
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np
from picamera import PiCamera, PiVideoFrameType

from general import WebSocketHandler  # Assuming this module exists

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def convert_frame_data_to_opencv_frame(frame_data: bytes) -> Optional[np.ndarray]:
    """Converts raw frame data (bytes) into an OpenCV frame (NumPy array)."""
    try:
        data = np.frombuffer(frame_data, dtype=np.uint8)
        frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
        if frame is None:
            raise ValueError("Failed to decode frame data")
        return frame
    except Exception as e:
        logging.error(f"Frame conversion error: {e}", exc_info=True)
        return None


def frames_are_different(frame1: np.ndarray, frame2: np.ndarray) -> bool:
    """Compares two frames and returns True if they are different, False otherwise."""
    try:
        return cv2.absdiff(frame1, frame2).any()
    except Exception as e:
        logging.error(f"Frame comparison error: {e}", exc_info=True)
        return False


class CameraStreamBuffer:
    """Buffers and streams camera frames over WebSocket."""

    def __init__(self, camera: PiCamera, websocket_handler: WebSocketHandler):
        self.camera = camera
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> None:
        """Writes frame data to buffer and streams over WebSocket if complete."""
        try:
            with self.lock:
                self.buffer.write(data)
                if self.camera.frame.complete and self.camera.frame.frame_type != PiVideoFrameType.sps_header:
                    frame_data = self.buffer.getvalue()
                    if self.websocket_handler.has_connections():
                        self.websocket_handler.broadcast(frame_data)
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logging.error(f"Camera stream buffer error: {e}", exc_info=True)


class MotionDetectionBuffer:
    """Buffers frames for motion detection."""

    def __init__(self, detect_motion: Callable[[np.ndarray, np.ndarray], None]):
        self.detect_motion = detect_motion
        self.frame_buffer = io.BytesIO()
        self.previous_frame: Optional[np.ndarray] = None
        self.current_frame: Optional[np.ndarray] = None
        self.lock = threading.Lock()

    def write(self, data: bytes) -> None:
        """Writes frame data to buffer and performs motion detection if complete."""
        try:
            with self.lock:
                self.frame_buffer.write(data)
                if data.startswith(b'\xff\xd8'):  # Start of a new JPEG image
                    self._process_frame()

        except Exception as e:
            logging.error(f"Motion detection buffer error: {e}", exc_info=True)

    def _process_frame(self) -> None:
        """Processes the complete frame in the buffer."""
        try:
            frame_data = self.frame_buffer.getvalue()
            frame = convert_frame_data_to_opencv_frame(frame_data)
            if frame is not None:
                self.previous_frame = self.current_frame
                self.current_frame = frame
                if self.previous_frame is not None:
                    if frames_are_different(self.previous_frame, self.current_frame):
                        self.detect_motion(self.previous_frame, self.current_frame)
            self.frame_buffer.seek(0)
            self.frame_buffer.truncate()
        except Exception as e:
            logging.error(f"Motion detection processing error: {e}", exc_info=True)

