import cv2
import supervision as sv
import numpy as np
from picamera2 import Picamera2, PreviewConfiguration
from typing import Tuple, List

def configure_camera(resolution: Tuple[int, int] = (640, 480)) -> Picamera2:
    """Configures the PiCamera2 with the specified resolution and returns the configured instance."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": resolution})
        picam2.configure(config)
        return picam2
    except Exception as e:
        raise RuntimeError(f"Camera configuration failed: {e}")

def detect_faces(image: np.ndarray, cascade_path: str) -> List[sv.Rectangle]:
    """Detects faces in the given image using the specified Haar cascade classifier."""
    try:
        detector = cv2.CascadeClassifier(cascade_path)
        grey = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = detector.detectMultiScale(grey, scaleFactor=1.3, minNeighbors=5)
        return [sv.Rectangle(x, y, w, h) for (x, y, w, h) in faces]
    except Exception as e:
        raise RuntimeError(f"Face detection failed: {e}")


def draw_rectangles(image: np.ndarray, rectangles: List[sv.Rectangle]) -> np.ndarray:
    """Draws rectangles on the image."""
    for rect in rectangles:
        cv2.rectangle(image, (int(rect.x1), int(rect.y1)), (int(rect.x2), int(rect.y2)), (0, 255, 0), 2)
    return image


def process_frame(image: np.ndarray, cascade_path: str) -> np.ndarray:
    """Processes a single frame by detecting faces and drawing rectangles around them."""
    faces = detect_faces(image, cascade_path)
    return draw_rectangles(image.copy(), faces)  # Return a copy to avoid modifying the original


def main_loop(cascade_path: str, resolution: Tuple[int, int] = (640, 480)):
    """Main loop for capturing and processing frames."""
    try:
        picam2 = configure_camera(resolution)
        picam2.start()
        cv2.startWindowThread()

        while True:
            im = picam2.capture_array()
            annotated = process_frame(im, cascade_path)
            cv2.imshow('Face Detection', annotated)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        if 'picam2' in locals():
            picam2.stop()
        cv2.destroyAllWindows()



if __name__ == "__main__":
    CASCADE_PATH = "haarcascade_frontalface_default.xml"  # Replace with actual path if needed
    main_loop(CASCADE_PATH)

