import RPi.GPIO as GPIO
import time
import datetime
import sqlite3
import random
import logging
import os

# Configure logging
logging.basicConfig(filename='air_quality_monitor.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Default configuration values
DEFAULT_CONFIG = {
    'gpio_button_pin': 17,
    'update_interval': 600,
    'database_file': 'air_quality.db',
    'logging_level': 'INFO'
}

# Function to load configuration from file
def load_config(config_file='config.txt'):
    config = DEFAULT_CONFIG.copy()
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    key, value = line.split('=', 1)
                    key = key.strip()
                    value = value.strip()
                    try:
                        # Attempt to convert to int or float
                        config[key] = eval(value)
                    except (NameError, SyntaxError):
                        # If not a number, keep as string
                        config[key] = value
        logging.info(f"Configuration loaded from {config_file}")
    except FileNotFoundError:
        logging.warning(f"Configuration file {config_file} not found. Using default configuration.")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}. Using default configuration.")
    return config

# Function to initialize GPIO
def initialize_gpio(gpio_pin):
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP) # Enable pull-up resistor
        logging.info(f"GPIO pin {gpio_pin} initialized.")
        return True
    except Exception as e:
        logging.error(f"Error initializing GPIO pin {gpio_pin}: {e}")
        return False

# Function to read sensor data (simulated)
def read_sensor_data():
    try:
        aqi = random.randint(0, 200)
        pm25 = random.uniform(5, 35)
        # Simulate sensor error with a 20% chance
        if random.random() < 0.2:
            return None, None
        return aqi, pm25
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None

# Function to store data in the database
def store_data(timestamp, aqi, pm25, db_file):
    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
        cursor.execute('''CREATE TABLE IF NOT EXISTS readings
                          (timestamp TEXT, aqi INTEGER, pm25 REAL)''')
        cursor.execute("INSERT INTO readings VALUES (?, ?, ?)", (timestamp, aqi, pm25))
        conn.commit()
        conn.close()
        logging.info(f"Data stored in database: Timestamp={timestamp}, AQI={aqi}, PM2.5={pm25}")
    except Exception as e:
        logging.error(f"Error storing data in database: {e}")

# Function to display data on e-ink display (simulated)
def display_data(aqi, pm25, alert_band):
    print(f"AQI: {aqi}, PM2.5: {pm25}, Alert Band: {alert_band}")
    logging.info(f"Display updated: AQI={aqi}, PM2.5={pm25}, Alert Band={alert_band}")

# Function to determine alert band
def determine_alert_band(aqi):
    if aqi < 50:
        return "GREEN"
    elif aqi < 100:
        return "YELLOW"
    elif aqi < 150:
        return "ORANGE"
    else:
        return "RED"

# Function to handle button press event
def button_pressed_callback(channel):
    global last_update_time
    current_time = time.time()
    if current_time - last_update_time >= config['update_interval']:
        try:
            timestamp = datetime.datetime.now().isoformat()
            aqi, pm25 = read_sensor_data()

            if aqi is not None and pm25 is not None:
                alert_band = determine_alert_band(aqi)
                display_data(aqi, pm25, alert_band)
                store_data(timestamp, aqi, pm25, config['database_file'])

                # Provide a brief explanation of the AQI value and its health implications
                if alert_band == "GREEN":
                    print("Air quality is good. No health impacts are expected.")
                elif alert_band == "YELLOW":
                    print("Air quality is moderate. Some people may experience irritation.")
                elif alert_band == "ORANGE":
                    print("Air quality is unhealthy for sensitive groups. People with respiratory or heart conditions may be affected.")
                else:
                    print("Air quality is unhealthy. Everyone may experience health effects.")

            else:
                print("Sensor error. Check sensor connection.")
                logging.warning("Sensor error detected.")

            last_update_time = current_time
        except Exception as e:
            logging.error(f"Error in button press callback: {e}")

# Main function
def main():
    global config, last_update_time
    config = load_config()

    # Set logging level based on config
    log_level = getattr(logging, config['logging_level'].upper(), None)
    if not isinstance(log_level, int):
        logging.warning(f"Invalid logging level: {config['logging_level']}. Using INFO level.")
        log_level = logging.INFO
    logging.getLogger().setLevel(log_level)

    gpio_pin = config['gpio_button_pin']
    if not 1 <= gpio_pin <= 27:
        logging.error(f"Invalid GPIO pin: {gpio_pin}. Must be between 1 and 27.")
        print("Invalid GPIO pin. Check configuration file.")
        return

    gpio_initialized = initialize_gpio(gpio_pin)

    last_update_time = time.time()

    try:
        if gpio_initialized:
            # Set up event detection for the button press
            GPIO.add_event_detect(gpio_pin, GPIO.FALLING, callback=button_pressed_callback, bouncetime=200)
            print("Air Quality Monitor running. Press the button to update.")
            logging.info("Air Quality Monitor started.")
            while True:
                time.sleep(1)  # Keep the script running
        else:
            print("GPIO initialization failed. Running without button input.")
            logging.warning("Running without button input due to GPIO initialization failure.")

            while True:
                current_time = time.time()
                if current_time - last_update_time >= config['update_interval']:
                    try:
                        timestamp = datetime.datetime.now().isoformat()
                        aqi, pm25 = read_sensor_data()

                        if aqi is not None and pm25 is not None:
                            alert_band = determine_alert_band(aqi)
                            display_data(aqi, pm25, alert_band)
                            store_data(timestamp, aqi, pm25, config['database_file'])

                            # Provide a brief explanation of the AQI value and its health implications
                            if alert_band == "GREEN":
                                print("Air quality is good. No health impacts are expected.")
                            elif alert_band == "YELLOW":
                                print("Air quality is moderate. Some people may experience irritation.")
                            elif alert_band == "ORANGE":
                                print("Air quality is unhealthy for sensitive groups. People with respiratory or heart conditions may be affected.")
                            else:
                                print("Air quality is unhealthy. Everyone may experience health effects.")

                        else:
                            print("Sensor error. Check sensor connection.")
                            logging.warning("Sensor error detected.")

                        last_update_time = current_time
                    except Exception as e:
                        logging.error(f"Error in main loop: {e}")
                time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
        logging.info("Program exiting due to KeyboardInterrupt.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if gpio_initialized:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        print("Program finished.")

if __name__ == "__main__":
    main()

