from smbus2 import SMBus

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x20

# Number of proximity sensors connected
NUM_SENSORS = 8

# Initialize I2C bus
try:
    bus = SMBus(1)  # Use 1 for Raspberry Pi 3 Model B+
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    sys.exit(1)

def read_sensor_data():
    """Reads data from the PCF8574 expander."""
    try:
        return bus.read_byte(PCF8574_ADDRESS)
    except Exception as e:
        print(f"Error reading from PCF8574: {e}")
        return None

def check_sensors():
    """Checks the state of each proximity sensor."""
    sensor_data = read_sensor_data()
    if sensor_data is None:
        return

    for i in range(NUM_SENSORS):
        if (sensor_data & (1 << i)) == 0:  # Active low
            print(f"Obstacle detected by sensor {i}")

def main():
    """Main function to continuously monitor proximity sensors."""
    try:
        while True:
            check_sensors()
            time.sleep(0.1)  # Polling interval
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        try:
            bus.close()
        except:
            pass
        print("Program finished.")

if __name__ == "__main__":
    main()

