    exit()

# Initialize the TCA9548A I2C multiplexer
try:
    multiplexer = adafruit_tca9548a.TCA9548A(i2c)
except ValueError as e:
    print(f"Error initializing multiplexer: {e}")
    exit()

# Initialize the BME280 sensor (temperature and humidity)
try:
    bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0])  # Sensor on multiplexer channel 0
except ValueError as e:
    print(f"Error initializing BME280 sensor: {e}")
    bme280 = None  # Set to None to avoid errors later

# Initialize the TSL2591 light sensor
try:
    tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[1])  # Sensor on multiplexer channel 1
except ValueError as e:
    print(f"Error initializing TSL2591 sensor: {e}")
    tsl2591 = None  # Set to None to avoid errors later

# Main loop to read and print sensor data
while True:
    try:
        # Read temperature and humidity from BME280
        if bme280:
