import serial
import time
import signal
import sys

# UART configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Global variable to track program execution
running = True

# Function to handle program termination signals
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    print('Shutting down gracefully...')
    running = False

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def is_valid_reading(temperature, humidity, pressure):
    """Validates sensor readings against reasonable ranges."""
    return -40 <= temperature <= 85 and 0 <= humidity <= 100 and 800 <= pressure <= 1200

def process_weather_data():
    """Reads weather data from UART, validates, and prints."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            while running:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            temperature, humidity, pressure = map(float, line.split(','))
                            if is_valid_reading(temperature, humidity, pressure):
                                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                                print(f'{timestamp} - Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%, Pressure: {pressure:.1f} hPa')
                            else:
                                print(f'Warning: Out-of-range reading: {line}')
                        except ValueError:
                            print(f'Warning: Malformed data: {line}')
                except serial.SerialException as e:
                    print(f"Serial communication error: {e}")
                    break  # Exit the loop on serial error
                except Exception as e:
                    print(f"An unexpected error occurred: {e}")
                    break # Exit the loop on unexpected error

    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except Exception as e:
        print(f"An error occurred during initialization: {e}")

if __name__ == "__main__":
    process_weather_data()
    print("Program finished.")

