# Temperature Logger for Raspberry Pi using UART
# Reads data from a UART sensor and logs it to a CSV file.

import serial
import time
import os
import sys

# Configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1  # seconds
LOG_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                celsius = float(line)
                return celsius
            except ValueError:
                print(f"Warning: Non-numeric data received: {line}")
                return None
        else:
            return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32

def log_temperature(log_file, timestamp, celsius, fahrenheit):
    """Logs the temperature data to a CSV file."""
    try:
        file_exists = os.path.isfile(log_file)
        with open(log_file, 'a') as file:
            if not file_exists:
                file.write("Timestamp,Celsius,Fahrenheit\n")
            file.write(f"{timestamp},{celsius},{fahrenheit}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            celsius_value = read_temperature(serial_connection)

            if celsius_value is not None:
                fahrenheit_value = convert_to_fahrenheit(celsius_value)
                current_timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_temperature(LOG_FILE, current_timestamp, celsius_value, fahrenheit_value)
                print(f"Timestamp: {current_timestamp}, Celsius: {celsius_value:.2f}, Fahrenheit: {fahrenheit_value:.2f}")

            time.sleep(1)  # Wait for 1 second

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

