import time
import Adafruit_DHT

# Define sensor and pin
DHT_SENSOR = Adafruit_DHT.DHT22
DHT_PIN = 22

# Initialize sensor
def initialize_sensor():
    """Initializes the DHT22 sensor."""
    time.sleep(1)  # Allow sensor to stabilize

# Read sensor data with retries
def read_sensor_data():
    """Reads temperature and humidity from the DHT22 sensor with retries."""
    max_retries = 2
    for attempt in range(max_retries + 1):
        humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
        if humidity is not None and temperature is not None:
            return temperature, humidity
        else:
            print(f"Attempt {attempt + 1}: Failed to read sensor data. Retrying...")
            time.sleep(0.1)
    print("Error: Could not read sensor data after multiple retries.")
    return None, None

# Display sensor data
def display_data(temperature, humidity):
    """Displays the temperature and humidity."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
    else:
        print("Error: Invalid sensor readings.")

# Main function
def main():
    """Main function to read and display temperature and humidity."""
    initialize_sensor()
    try:
        while True:
            temperature, humidity = read_sensor_data()
            display_data(temperature, humidity)
            time.sleep(3)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

