import time
import requests
import Adafruit_DHT
import RPi.GPIO as GPIO

# Define sensor and pin
DHT_SENSOR = Adafruit_DHT.DHT11
DHT_PIN = 4

# Define API endpoint
API_ENDPOINT = 'http://127.0.0.1:5000/data'

def read_sensor_data():
    """Reads temperature and humidity from the DHT11 sensor."""
    humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
    return temperature, humidity

def send_data_to_server(temperature, humidity):
    """Sends temperature and humidity data to the Flask API."""
    data = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(API_ENDPOINT, json=data)
        print(f"Data sent. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending data: {e}")

def main():
    """Main function to read sensor data and send it to the server."""
    try:
        while True:
            temperature, humidity = read_sensor_data()

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                send_data_to_server(temperature, humidity)
            else:
                print("Failed to retrieve data from sensor")

            time.sleep(5)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

