import serial
import time

# Configuration for the serial port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
SLEEP_DURATION = 1  # seconds

def read_sensor_data(serial_connection):
    """Reads a line from the serial port and returns it."""
    try:
        return serial_connection.readline().decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_sensor_data(data):
    """Parses the sensor data into temperature and humidity."""
    if not data:
        return None, None
    try:
        temperature, humidity = data.split(',')
        return float(temperature), float(humidity)
    except ValueError:
        print(f"Invalid data format: {data}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds the defined thresholds."""
    if temperature > TEMPERATURE_THRESHOLD:
        print('Alert: High Temperature Detected!')
    if humidity > HUMIDITY_THRESHOLD:
        print('Alert: High Humidity Detected!')

def log_data(temperature, humidity):
    """Logs the temperature and humidity data to a file."""
    try:
        with open('environmental_data.log', 'a') as log_file:
            log_file.write(f"{temperature},{humidity}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read, process, and log sensor data."""
    serial_connection = None
    try:
        # Initialize serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to serial port {SERIAL_PORT}")

        while True:
            # Read data from the serial port
            sensor_data = read_sensor_data(serial_connection)

            # Process the sensor data
            temperature, humidity = process_sensor_data(sensor_data)

            # If data is valid, log and check thresholds
            if temperature is not None and humidity is not None:
                log_data(temperature, humidity)
                check_thresholds(temperature, humidity)

            # Wait before the next reading
            time.sleep(SLEEP_DURATION)

    except serial.SerialException as e:
        print(f"Serial port error: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the serial port is closed
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

