#!/usr/bin/python3

"""
Control an LED based on a switch connected to an MCP23017 I2C GPIO expander.
"""

import time
from MCP23017_I2C import GPIO_CHIP, MCP23017Error

# Constants
MCP23017_ADDRESS = 0x27  # I2C address of the MCP23017 chip
PI_MODEL = 1  # 0 for Model A, B Rev 2 or B+; 1 for Model B Rev 1
LED_PIN = 0  # GPA0
SWITCH_PIN = 7  # GPB7
SLEEP_TIME = 0.1  # seconds
MAX_RETRY_COUNT = 3  # Maximum retry attempts for I2C operations


def initialize_gpio(address, pi_model):
    """Initializes the MCP23017 chip."""
    try:
        gpio_chip = GPIO_CHIP(address, pi_model)
        gpio_chip.setup(LED_PIN, 'OUT', 'A')
        gpio_chip.setup(SWITCH_PIN, 'IN', 'B')
        gpio_chip.pullup(SWITCH_PIN, 1, 'B')  # Enable pull-up resistor
        return gpio_chip
    except MCP23017Error as e:
        raise IOError(f"Failed to initialize MCP23017: {e}")


def read_switch_state(gpio_chip):
    """Reads the state of the switch pin."""
    try:
        return gpio_chip.input(SWITCH_PIN, 'B')
    except MCP23017Error as e:
        raise IOError(f"Failed to read switch state: {e}")


def control_led(gpio_chip, state):
    """Controls the LED based on the given state."""
    try:
        gpio_chip.output(LED_PIN, state, 'A')
        print(f"Led {'ON' if state else 'OFF'}")  # Print only on state change
    except MCP23017Error as e:
        raise IOError(f"Failed to control LED: {e}")


def main():
    """Main function to control the LED based on switch input."""
    try:
        gpio_chip = initialize_gpio(MCP23017_ADDRESS, PI_MODEL)
        last_led_state = None  # Store the last known LED state

        while True:
            try:
                switch_is_pressed = read_switch_state(gpio_chip)
                led_should_be_on = not switch_is_pressed  # Invert switch state for LED

                if led_should_be_on != last_led_state:
                    control_led(gpio_chip, led_should_be_on)
                    last_led_state = led_should_be_on

                time.sleep(SLEEP_TIME)

            except IOError as e:
                print(f"Error during operation: {e}")
                # Implement retry logic or other error handling as needed
                time.sleep(SLEEP_TIME)  # Prevent excessive error printing

    except IOError as e:
        print(f"Initialization error: {e}")
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        # Ensure LED is turned off on exit
        if 'gpio_chip' in locals() and gpio_chip is not None:  # Check if gpio_chip is initialized
            try:
                control_led(gpio_chip, 0)
            except Exception as e: # Catch any potential errors during cleanup
                print(f"Error during cleanup: {e}")
        exit()


if __name__ == "__main__":
    main()

