import time
import sys
import random
try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not found, using dummy GPIO")
    GPIO = None

# Constants for GPIO pins (using BCM numbering)
LED_PIN = 17  # GPIO17 (physical pin 11)
BUTTON_PIN = 5  # GPIO5 (physical pin 29)

# Function to initialize GPIO pins
def initialize_gpio():
    """Initializes GPIO pins for LED and button."""
    if GPIO is None:
        return  # Skip initialization if running without RPi.GPIO

    try:
        GPIO.setmode(GPIO.BCM)  # Use BCM numbering
        GPIO.setup(LED_PIN, GPIO.OUT)  # LED pin as output
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Button pin as input with pull-down resistor
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)

# Function to toggle the LED state
def toggle_led(led_pin):
    """Toggles the state of the LED."""
    if GPIO is None:
        return  # Skip LED control if running without RPi.GPIO

    try:
        current_state = GPIO.input(led_pin)
        new_state = not current_state
        GPIO.output(led_pin, new_state)
        return new_state
    except Exception as e:
        print(f"Error toggling LED: {e}", file=sys.stderr)
        return False

# Function to read the button state
def read_button_state(button_pin):
    """Reads the current state of the button."""
    if GPIO is None:
        return False  # Simulate button release if running without RPi.GPIO

    try:
        return GPIO.input(button_pin) == GPIO.HIGH
    except Exception as e:
        print(f"Error reading button state: {e}", file=sys.stderr)
        return False

# Main function
def main():
    """Main function to control the LED based on button input."""
    initialize_gpio()
    led_state = False  # Initial LED state (off)

    try:
        while True:
            button_pressed = read_button_state(BUTTON_PIN)

            if button_pressed:
                led_state = toggle_led(LED_PIN)
                if led_state:
                    print("Button pressed! LED is ON")
                else:
                    print("Button released! LED is OFF")
            else:
                if led_state:
                    print("Button released! LED is OFF")
                    led_state = False

            time.sleep(0.1)  # Short delay to prevent busy-waiting

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if GPIO is not None:
            GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off on exit
            GPIO.cleanup()  # Clean up GPIO settings
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

