import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom protocol module

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # Seconds

# Global Variables (Encapsulated in a dictionary for better organization)
STATE = {
    'log_file': DEFAULT_LOG_FILE,
    'receiving': False,
    'receiver_thread': None,
    'receive_event': threading.Event()
}


# Documentation (using a function with a descriptive name)
def display_help(command=None):
    """Displays help information for available commands."""
    help_messages = {
        None: "Available commands: help, start, stop, display, send, write, exit",
        'help': "Help: help [command]. Available subcommands: help, start, stop, display, send, write, exit",
        'start': "Start receiving data and logging to file: start <filename>",
        'stop': "Stop receiving data: stop",
        'display': "Display the contents of the log file: display",
        'send': "Send data using DOGProtocol: send <data>",
        'write': "Manually write data to the log file: write <data>",
        'exit': "Exit the program: exit"
    }
    print(help_messages.get(command, "Invalid help command."))


# Functional approach to writing data with error handling
def write_to_log(log_file, data):
    """Writes data to the log file with error handling."""
    try:
        with open(log_file, 'a') as f:
            f.write(data + '\n')
    except Exception as e:
        print(f"Error writing to log file: {e}")


# Event-driven data reception
def receive_data(log_file, receive_event):
    """Continuously receives data and logs it to a file."""
    try:
        while not receive_event.is_set():
            data = DOG.receive()  # Your custom receive function
            if data:  # Check if data is not empty/None
                write_to_log(log_file, data)
            time.sleep(POLL_INTERVAL)  # Prevent busy-waiting
    except Exception as e:
        print(f"Error in receive_data: {e}")
    finally:
        print("Data reception stopped.")


def start_receiving(filename):
    """Starts the data reception thread."""
    if STATE['receiving']:
        print("Already receiving data.")
        return

    try:
        STATE['log_file'] = filename
        STATE['receive_event'].clear()  # Reset event
        STATE['receiving'] = True
        STATE['receiver_thread'] = threading.Thread(target=receive_data, args=(STATE['log_file'], STATE['receive_event']), daemon=True)
        STATE['receiver_thread'].start()
        print(f"Receiving data and logging to: {STATE['log_file']}")
    except Exception as e:
        print(f"Error starting reception: {e}")
        STATE['receiving'] = False  # Reset state in case of error


def stop_receiving():
    """Stops the data reception thread."""
    if not STATE['receiving']:
        print("Not currently receiving data.")
        return

    try:
        STATE['receive_event'].set()  # Signal the thread to stop
        if STATE['receiver_thread'] and STATE['receiver_thread'].is_alive():
            STATE['receiver_thread'].join()  # Wait for thread to finish
        STATE['receiving'] = False
        print("Data reception stopped.")
    except Exception as e:
        print(f"Error stopping reception: {e}")
        STATE['receiving'] = False # Ensure state is reset


def display_log():
    """Displays the contents of the log file."""
    if not STATE['receiving']:
        try:
            with open(STATE['log_file'], 'r') as f:
                print(f.read())
        except FileNotFoundError:
            print(f"Log file not found: {STATE['log_file']}")
        except Exception as e:
            print(f"Error reading log file: {e}")
    else:
        print("Cannot display log while receiving data.")


def send_data(data_string):
    """Sends data using DOGProtocol."""
    if STATE['receiving']:
        print("Cannot send data while receiving.")
        return

    try:
        DOG.send(data_string)  # Your custom send function
        print(f"Sent: {data_string}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_data(data_string):
    """Manually writes data to the log file."""
    if STATE['receiving']:
        print("Cannot write data while receiving.")
        return

    write_to_log(STATE['log_file'], data_string)
    print(f"Wrote: {data_string}")


def parse_command(command):
    """Parses the user command and calls the appropriate function."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    commands = {
        'help': lambda: display_help(args[0] if args else None),
        'start': lambda: start_receiving(args[0] if args else DEFAULT_LOG_FILE),
        'stop': lambda: stop_receiving(),
        'display': lambda: display_log(),
        'send': lambda: send_data(" ".join(args)),
        'write': lambda: write_data(" ".join(args)),
        'exit': lambda: exit_program()
    }

    if cmd in commands:
        commands[cmd]()
    else:
        print("Invalid command. Type 'help' for available commands.")


def exit_program():
    """Exits the program cleanly."""
    stop_receiving()  # Ensure reception is stopped
    GPIO.cleanup()      # Clean up GPIO pins
    print("Exiting program.")
    exit()


def main():
    """Main function to run the program."""
    try:
        while True:
            try:
                command = input("JAYES@ROVER53:\t")
            except EOFError:  # Handle Ctrl+D
                print("\nExiting program (EOF received).")
                break
            except KeyboardInterrupt: # Handle Ctrl+C
                print("\nKeyboardInterrupt received.")
                continue
            parse_command(command.strip())
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    main()

