    """Reads the value from the specified IR sensor pin."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor on pin {pin}: {e}")
        return None  # Return None to indicate an error


def determine_steering_action(left_value, right_value):
    """Determines the robot's steering action based on sensor readings."""
    if left_value is None or right_value is None:
        return "Error"

    if left_value == 0 and right_value == 0:
        return "Forward"
    elif left_value == 1 and right_value == 0:
        return "Turn Left"
    elif left_value == 0 and right_value == 1:
        return "Turn Right"
    else:
        return "Search"


