                print_gpio_log()
                last_print_time = current_time
    except KeyboardInterrupt:
        print("\nExiting gracefully (KeyboardInterrupt).")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

