    elif revision_code == "90003c":
        model = "Compute Module"
    elif revision_code == "90003d":
        model = "Compute Module"
    elif revision_code == "90003e":
        model = "Compute Module"
    elif revision_code == "90003f":
        model = "Compute Module"
    return model


def get_gpio_num(revision_code):
    """Determines the number of GPIO lines based on the revision code.

    Args:
        revision_code (str): The Raspberry Pi board revision code.

    Returns:
        int: The number of GPIO lines available (17 for early models, 26 for later models).
    """
    # Check for early models (pre-revision 2)
    if revision_code in ("0000", "0001", "000d", "000e", "000f", "0010", "0012", "0013"):
        return 17
    else:
        return 26


def setup_gpio_pins(gpio_pins, debounce_time):
    """Sets up the specified GPIO pins as inputs with pull-up resistors and event detection.

    Args:
        gpio_pins (list): A list of GPIO pin numbers to set up.
        debounce_time (int): The debounce time in milliseconds.
    """
    for pin in gpio_pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.add_event_detect(
                pin,
                GPIO.BOTH,
                callback=lambda channel: log_gpio_event(channel, GPIO.input(channel)),
                bouncetime=debounce_time,
            )
            print(f"GPIO {pin} set up as input with pull-up resistor.")
        except Exception as e:
            print(f"Error setting up GPIO {pin}: {e}")


def log_gpio_event(pin, value):
    """Logs a GPIO event to the in-memory log.

    Args:
        pin (int): The GPIO pin number.
        value (int): The current value of the pin (0 or 1).
    """
    timestamp = time.time()
    event = (timestamp, pin, value)
    gpio_log.append(event)
    if len(gpio_log) > GPIO_LOG_SIZE:
        gpio_log.pop(0)  # Keep only the most recent events


def print_gpio_log():
    """Prints the contents of the GPIO event log."""
    print("Current GPIO event log:")
    for timestamp, pin, value in gpio_log:
        print(f"  GPIO {pin}: {value} (at {timestamp:.2f})")


def signal_handler(sig, frame):
    """Handles signals (e.g., Ctrl+C) to ensure a clean exit."""
    global running
    print("\nExiting gracefully...")
    running = False


def main():
    """Main function to set up GPIO monitoring and handle command-line arguments."""
    global running

    # Set up signal handling for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Parse command-line arguments
    parser = argparse.ArgumentParser(
        description="Monitors GPIO pins on a Raspberry Pi and logs events."
    )
    parser.add_argument(
        "-d",
        "--debounce",
        type=int,
        default=DEFAULT_DEBOUNCE_TIME,
        help="Debounce time in milliseconds (default: {})".format(
            DEFAULT_DEBOUNCE_TIME
        ),
    )
    args = parser.parse_args()

    debounce_time = args.debounce

    # Initialize GPIO
    try:
        GPIO.setmode(GPIO.BCM)  # Use Broadcom pin numbering
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

    # Get Raspberry Pi model and revision code
    try:
        with open("/proc/cpuinfo", "r") as f:
            cpuinfo = f.read()
        revision_line = next(
            (line for line in cpuinfo.splitlines() if line.startswith("Revision")),
            None,
        )
        if revision_line:
            revision_code = revision_line.split(":")[1].strip()
            model = get_raspi_model(revision_code)
            gpio_count = get_gpio_num(revision_code)
            print(f"Detected Raspberry Pi Model: {model} (GPIO count: {gpio_count})")
        else:
            print("Could not determine Raspberry Pi model.")
            revision_code = "Unknown"
    except FileNotFoundError:
        print("Error: /proc/cpuinfo not found.  Are you running on a Raspberry Pi?")
        sys.exit(1)
    except Exception as e:
        print(f"Error getting Raspberry Pi model: {e}")
        revision_code = "Unknown"

    # Set up GPIO pins based on the detected model
    try:
        if revision_code in gpio_ch:
            gpio_pins = gpio_ch[revision_code]
        else:
            print("Using default GPIO pins (Model B+).")
            gpio_pins = gpio_ch["B"]  # Default to Model B+ pins
        setup_gpio_pins(gpio_pins, debounce_time)
    except Exception as e:
        print(f"Error setting up GPIO pins: {e}")
        GPIO.cleanup()
        sys.exit(1)

    # Main loop: monitor GPIO pins and print the log periodically
    print("Monitoring GPIO pins. Press Ctrl+C to exit.")
    last_print_time = time.time()
    try:
        while running:
            time.sleep(1)  # Check every second
            current_time = time.time()
            if current_time - last_print_time >= 5:
                print_gpio_log()
                last_print_time = current_time
    except KeyboardInterrupt:
        print("\nExiting gracefully (KeyboardInterrupt).")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

