import time

# Define the GPIO pins for the RGB LED channels (BCM numbering)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22

# Define the PWM frequency in Hz
PWM_FREQUENCY = 100

# Define the duty cycles for each color
RED_DUTY_CYCLE = 1.0
GREEN_DUTY_CYCLE = 0.5
BLUE_DUTY_CYCLE = 0.25

# Define the display duration in seconds
DISPLAY_DURATION = 2


def initialize_rgb_led(red_pin, green_pin, blue_pin, frequency):
    """Initializes the RGB LED channels with PWM."""
    try:
        red = PWMOutputDevice(red_pin, frequency=frequency)
        green = PWMOutputDevice(green_pin, frequency=frequency)
        blue = PWMOutputDevice(blue_pin, frequency=frequency)
        return red, green, blue
    except Exception as e:
        print(f"Error initializing RGB LED: {e}")
        return None, None, None


def set_rgb_led_color(red, green, blue, red_duty_cycle, green_duty_cycle, blue_duty_cycle):
    """Sets the color of the RGB LED using PWM duty cycles."""
    try:
        red.value = red_duty_cycle
        green.value = green_duty_cycle
        blue.value = blue_duty_cycle
    except Exception as e:
        print(f"Error setting RGB LED color: {e}")


def display_color(red, green, blue, duration):
    """Displays the current color for a specified duration."""
    try:
        time.sleep(duration)
    except Exception as e:
        print(f"Error during display: {e}")


def cleanup_rgb_led(red, green, blue):
    """Stops PWM and releases GPIO resources."""
    try:
        if red:
            red.close()
        if green:
            green.close()
        if blue:
            blue.close()
    except Exception as e:
        print(f"Error during cleanup: {e}")


