    red, green, blue = initialize_rgb_led(RED_PIN, GREEN_PIN, BLUE_PIN, PWM_FREQUENCY)

    if red and green and blue:
        try:
            set_rgb_led_color(red, green, blue, RED_DUTY_CYCLE, GREEN_DUTY_CYCLE, BLUE_DUTY_CYCLE)
            display_color(red, green, blue, DISPLAY_DURATION)
        finally:
            cleanup_rgb_led(red, green, blue)
    else:
        print("RGB LED initialization failed. Exiting.")


if __name__ == "__main__":
    main()

