import smbus2
import contextlib

# I2C device helper for Raspberry Pi using a functional approach

def create_i2c_bus(bus_number=1):
    """Creates an I2C bus object."""
    try:
        return smbus2.SMBus(bus_number)
    except Exception as e:
        raise RuntimeError(f"Failed to create I2C bus: {e}")

def check_device_acknowledgment(bus, address):
    """Checks if the I2C device acknowledges at the given address."""
    try:
        bus.read_byte(address)
        return True
    except (OSError, IOError):
        return False

def write_byte_to_register(bus, address, register, value):
    """Writes a byte to a specific register on the I2C device."""
    try:
        bus.write_byte_data(address, register, value)
    except (OSError, IOError) as e:
        raise RuntimeError(f"Failed to write byte to register: {e}")

def read_byte_from_register(bus, address, register):
    """Reads a byte from a specific register on the I2C device."""
    try:
        return bus.read_byte_data(address, register)
    except (OSError, IOError) as e:
        raise RuntimeError(f"Failed to read byte from register: {e}")

class I2CDevice:
    """Represents an I2C device and provides methods for interaction."""

    def __init__(self, address, bus_number=1):
        """Initializes the I2C device."""
        self.address = address
        self.bus_number = bus_number
        self.bus = None

        if not (0 <= self.address <= 127):
            raise ValueError("Invalid I2C address. Must be between 0 and 127.")

        try:
            self.bus = create_i2c_bus(self.bus_number)
            if not check_device_acknowledgment(self.bus, self.address):
                self.bus.close()  # Close the bus if device not found
                raise RuntimeError(f"I2C device not found at address {self.address}")
        except RuntimeError as e:
            raise  # Re-raise bus creation or device check errors

    def __enter__(self):
        """Context manager entry point."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, ensuring bus is closed."""
        if self.bus:
            self.bus.close()
            self.bus = None

    def write_byte(self, register, value):
        """Writes a byte to a register."""
        if not 0 <= value <= 255:
            raise ValueError("Value must be between 0 and 255.")
        write_byte_to_register(self.bus, self.address, register, value)

    def read_byte(self, register):
        """Reads a byte from a register."""
        return read_byte_from_register(self.bus, self.address, register)

    def close(self):
        """Closes the I2C bus connection."""
        if self.bus:
            self.bus.close()
            self.bus = None

