import time
import smbus2 as smbus
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# CCS811 I2C address and register map
CCS811_ADDRESS = 0x5A
CCS811_STATUS = 0x00
CCS811_MEAS_MODE = 0x01
CCS811_ALG_RESULT_DATA = 0x02
CCS811_SENS_DATA = 0x05
CCS811_NTC = 0x06
CCS811_THRESHOLDS = 0x10
CCS811_BASELINE = 0x11
CCS811_HW_ID = 0x20
CCS811_HW_VERSION = 0x21
CCS811_BOOT_VERSION = 0x23
CCS811_APP_VERSION = 0x24
CCS811_ERROR_ID = 0xE0
CCS811_SW_RESET = 0x1B

# Measurement modes
CCS811_MODE_1SEC = 0x13
CCS811_MODE_10SEC = 0x0D


class CCS811:
    """Driver for the CCS811 gas sensor."""

    def __init__(self, bus_num=1, address=CCS811_ADDRESS, mode=CCS811_MODE_1SEC):
        """Initialize the CCS811 sensor.

        Args:
            bus_num (int): I2C bus number.
            address (int): I2C address of the sensor.
            mode (int): Measurement mode.

        Raises:
            IOError: If the sensor is not found or communication fails.
        """
        self.bus_num = bus_num
        self.address = address
        self.mode = mode
        self.bus = None

        try:
            self.bus = smbus.SMBus(self.bus_num)
            if self.get_hw_id() != 0x81:
                raise IOError("CCS811 not found at address 0x{:02X}".format(self.address))
            self.begin()
        except Exception as e:
            logger.error(f"Error initializing CCS811: {e}")
            raise

    def get_hw_id(self):
        """Get the hardware ID of the sensor."""
        try:
            return self.bus.read_byte_data(self.address, CCS811_HW_ID)
        except Exception as e:
            logger.error(f"Error reading HW ID: {e}")
            return None

    def begin(self):
        """Start measuring."""
        try:
            self.bus.write_byte_data(self.address, CCS811_MEAS_MODE, self.mode)
        except Exception as e:
            logger.error(f"Error beginning measurement: {e}")
            raise

    def available(self):
        """Check if new data is available."""
        try:
            status = self.bus.read_byte_data(self.address, CCS811_STATUS)
            return (status & 0x08) != 0
        except Exception as e:
            logger.error(f"Error checking availability: {e}")
            return False

    def get_eco2(self):
        """Get the CO2 concentration in ppm."""
        try:
            if self.available():
                data = self.bus.read_i2c_block_data(self.address, CCS811_ALG_RESULT_DATA, 2)
                return data[0] * 256 + data[1]
            else:
                return None
        except Exception as e:
            logger.error(f"Error reading CO2: {e}")
            return None

    def close(self):
        """Close the I2C bus."""
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")


def main():
    """Main function to read and print CO2 data."""
    try:
        sensor = CCS811()
        for _ in range(5):
            co2 = sensor.get_eco2()
            if co2 is not None:
                logger.info("CO2: %d ppm", co2)
            time.sleep(2)
    except KeyboardInterrupt:
        logger.info("Exiting...")
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if 'sensor' in locals():
            sensor.close()


if __name__ == "__main__":
    main()

