"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a driver for the Maxim DS1338 RTC chip, utilizing the I2C interface.
It offers functionalities to read and write date and time information to the RTC.
"""

import smbus
from datetime import datetime
import contextlib

__author__ = "Thomas Kaulke"
__email__ = "kaulketh@gmail.com"

# Constants for RTC registers
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
REG_STATUS = 0x0F  # Added Status Register address


def _bcd_to_int(bcd: int) -> int:
    """Decode a 2x4bit BCD value to an integer."""
    return int(str(bcd // 16) + str(bcd % 16))


def _int_to_bcd(n: int) -> int:
    """Encode an integer to BCD format."""
    tens, units = divmod(n, 10)
    return (tens << 4) | units


def _read_register(bus: smbus.SMBus, address: int, register: int) -> int:
    """Read a single byte from the specified register."""
    try:
        return bus.read_byte_data(address, register)
    except OSError as e:
        raise IOError(f"Error reading register 0x{register:02X}: {e}") from e


def _write_register(bus: smbus.SMBus, address: int, register: int, value: int) -> None:
    """Write a single byte to the specified register."""
    try:
        bus.write_byte_data(address, register, value)
    except OSError as e:
        raise IOError(f"Error writing to register 0x{register:02X}: {e}") from e


def _read_time_data(bus: smbus.SMBus, address: int) -> tuple[int, ...]:
    """Read time data from the RTC registers."""
    registers = [REG_SECONDS, REG_MINUTES, REG_HOURS, REG_DAY, REG_DATE, REG_MONTH, REG_YEAR]
    return tuple(_bcd_to_int(_read_register(bus, address, reg)) for reg in registers)


def _write_time_data(bus: smbus.SMBus, address: int, data: tuple[int, ...]) -> None:
    """Write time data to the RTC registers."""
    registers = [REG_SECONDS, REG_MINUTES, REG_HOURS, REG_DAY, REG_DATE, REG_MONTH, REG_YEAR]
    for reg, value in zip(registers, data):
        _write_register(bus, address, reg, _int_to_bcd(value))


