import RPi.GPIO as GPIO
import time
import argparse
import json
import smbus
import os

# Define GPIO pin for RF transmitter (default)
DEFAULT_GPIO_PIN = 17
# Default number of times to repeat the transmission
DEFAULT_TRANSMISSION_REPEAT = 3

def load_config(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        print(f"Error: Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in {config_file}")
        return None

def get_current_time():
    """Gets the current time from the RTC module or system clock."""
    try:
        bus = smbus.SMBus(1)  # Use I2C bus 1
        bus.write_byte(0x68, 0x00)
        data = bus.read_i2c_block_data(0x68, 0x00, 7)
        seconds = bcd_to_decimal(data[0] & 0x7F)
        minutes = bcd_to_decimal(data[1])
        hours = bcd_to_decimal(data[2] & 0x3F)
        return (hours, minutes, seconds)
    except Exception as e:
        print(f"Error reading RTC: {e}. Using system time.")
        return time.localtime()[3:6]  # Return hours, minutes, seconds from system time

def bcd_to_decimal(bcd):
    """Converts a BCD value to decimal."""
    return (bcd >> 4) * 10 + (bcd & 0x0F)

def transmit_rf_code(gpio_pin, rf_code, transmission_repeat):
    """Transmits the RF code using OOK modulation."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(gpio_pin, GPIO.OUT)

        for _ in range(transmission_repeat):
            for bit in rf_code:
                if bit == '1':
                    GPIO.output(gpio_pin, GPIO.HIGH)
                else:
                    GPIO.output(gpio_pin, GPIO.LOW)
                time.sleep(0.001)  # 1ms pulse width
            time.sleep(0.01)  # 10ms gap between repeats
        print(f"Transmitted RF code: {rf_code} on GPIO {gpio_pin} with repeat {transmission_repeat}")

    except Exception as e:
        print(f"Error transmitting RF code: {e}")
    finally:
        GPIO.cleanup()

def main():
    """Main function to control irrigation zones."""
    parser = argparse.ArgumentParser(description="Control irrigation zones using RF remote control.")
    parser.add_argument("zone", choices=["zone1", "zone2"], help="The irrigation zone to control.")
    parser.add_argument("action", choices=["on", "off"], help="The action to perform (on or off).")
    args = parser.parse_args()

    config = load_config("irrigation_config.json")
    if config is None:
        exit(1)

    gpio_pin = config.get("gpio_pin", DEFAULT_GPIO_PIN)
    transmission_repeat = config.get("transmission_repeat", DEFAULT_TRANSMISSION_REPEAT)

    if args.zone == "zone1":
        if args.action == "on":
            rf_code = config.get("zone1_on")
        else:
            rf_code = config.get("zone1_off")
    else:
        if args.action == "on":
            rf_code = config.get("zone2_on")
        else:
            rf_code = config.get("zone2_off")

    if rf_code is None:
        print("Error: Invalid configuration. Check irrigation_config.json.")
        exit(1)

    current_time = get_current_time()
    print(f"Current time: {current_time}")

    transmit_rf_code(gpio_pin, rf_code, transmission_repeat)

if __name__ == "__main__":
    main()

