import time
import RPi.GPIO as GPIO

# Configuration constants for the radiation monitoring system
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1

def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for alarm output."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_radiation_level(serial_port):
    """Reads a line from the serial port and returns the radiation level as a float."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Invalid data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}")
        return None

def control_alarm(pin, radiation_level, threshold):
    """Controls the alarm GPIO pin based on the radiation level."""
    if radiation_level is not None:
        GPIO.output(pin, GPIO.HIGH if radiation_level > threshold else GPIO.LOW)

def main():
    """Main function to continuously monitor radiation levels."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    initialize_gpio(ALARM_GPIO_PIN)

    try:
        while True:
            radiation_value = read_radiation_level(serial_connection)
            if radiation_value is not None:
                print(f'Radiation Level: {radiation_value} µSv/h')
                control_alarm(ALARM_GPIO_PIN, radiation_value, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

