# gps_parse.py - Read GPS data from UART and extract coordinates
# For Raspberry Pi 5 in an industrial automation context

import serial
import time

# --- Configuration ---
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600             # Standard GPS baud rate
READ_TIMEOUT = 1             # Timeout for reading serial data (seconds)

# --- Helper Functions ---
def safe_float(value):
    """
    Safely converts a value to a float, returning None on failure.
    """
    try:
        return float(value)
    except (ValueError, TypeError):
        return None

def safe_int(value):
    """
    Safely converts a value to an integer, returning None on failure.
    """
    try:
        return int(value)
    except (ValueError, TypeError):
        return None

def decode_coordinate(coordinate_str):
    """
    Converts GPS coordinate string (ddmm.mmmm) to decimal degrees.
    """
    if not coordinate_str:
        return None

    try:
        parts = coordinate_str.split('.')
        degrees = int(parts[0][:-2])
        minutes = safe_float(".".join(parts[1:]))
        if minutes is None:
            return None
        decimal_degrees = degrees + (minutes / 60.0)
        return decimal_degrees
    except (ValueError, IndexError, TypeError):
        return None

def parse_gprmc_data(data):
    """
    Parses GPRMC (Recommended Minimum Specific GPS/Transit Data) sentences.
    """
    try:
        if not data.startswith('$GPRMC'):
            return None  # Not a GPRMC sentence, ignore

        sdata = data.split(',')

        if sdata[2] == 'V':
            return None  # 'V' indicates invalid data

        latitude = decode_coordinate(sdata[3])
        latitude_direction = sdata[4]  # 'N' or 'S'
        longitude = decode_coordinate(sdata[5])
        longitude_direction = sdata[6]  # 'E' or 'W'

        if latitude is None or longitude is None:
            return None

        # Apply direction to latitude and longitude
        if latitude_direction == 'S':
            latitude = -latitude
        if longitude_direction == 'W':
            longitude = -longitude

        return latitude, longitude

    except (IndexError, ValueError, TypeError):
        return None

# --- Main Function ---
def main():
    """
    Main function to read GPS data and extract coordinates.
    """
    print("Starting GPS data reader...")

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Connected to GPS on {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return

    try:
        while True:
            try:
                data = ser.readline().decode('utf-8', errors='ignore').strip()
            except serial.SerialException as e:
                print(f"Error reading from serial port: {e}")
                break  # Exit loop if read fails

            if data:
                result = parse_gprmc_data(data)
                if result:
                    latitude, longitude = result
                    print(f"Latitude: {latitude:.6f}, Longitude: {longitude:.6f}")

            time.sleep(1)  # Wait for 1 second

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        try:
            ser.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")

# --- Run the Main Function ---
if __name__ == "__main__":
    main()

