from flask import Flask, Response, request, jsonify, abort
import serial
import time
import os

# Initialize the Flask application
app = Flask(__name__)

# Data storage (using a list of dictionaries)
TASKS = [
    {'id': 1, 'name': 'Get Coffee', 'done': False},
    {'id': 2, 'name': 'Write Tutorial', 'done': False}
]

# Serial port configuration (adjust as needed)
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def create_serial_connection():
    """Establishes a serial connection."""
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def send_scpi_command(command):
    """Sends an SCPI command to the instrument and returns the response."""
    ser = create_serial_connection()
    if ser is None:
        return "Error: Could not open serial port."

    try:
        ser.write((command + '\n').encode())
        time.sleep(0.1)  # Give the instrument time to respond
        response = ser.read_all().decode()
        return response
    except Exception as e:
        print(f"Error communicating with instrument: {e}")
        return f"Error: {e}"
    finally:
        if ser and ser.is_open:
            ser.close()

def get_instrument_version():
    """Retrieves the instrument's version information."""
    response = send_scpi_command("*IDN?")
    return response


# API Endpoints
@app.route('/version', methods=['GET'])
def get_version():
    """Returns the instrument's version information."""
    version_info = get_instrument_version()
    return Response(version_info, mimetype='text/html')


@app.route('/getdata', methods=['GET'])
def get_all_tasks():
    """Returns all tasks in JSON format."""
    return jsonify(TASKS)


@app.route('/getset/<int:task_id>', methods=['GET'])
def get_task_by_id(task_id):
    """Returns a specific task by ID."""
    task = next((task for task in TASKS if task['id'] == task_id), None)
    if task:
        return jsonify(task)
    else:
        abort(404)


@app.route('/getpost/<int:task_id>/<name>', methods=['GET'])
def create_task(name, task_id):
    """Creates a new task."""
    task = {
        'id': task_id,
        'name': name,
        'done': False
    }
    TASKS.append(task)
    return jsonify(TASKS)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json_data():
    """Handles JSON data posted to the server."""
    if request.method == 'GET':
        return jsonify(TASKS)

    elif request.method == 'POST':
        if 'application/json' in request.headers.get('Content-Type', ''):
            try:
                task = request.get_json()
            except Exception as e:
                abort(400, description=f"Invalid JSON data: {e}")
        else:
            task = request.get_data()

        if isinstance(task, dict):  # Check if task is a dictionary
            task['id'] = TASKS[-1]['id'] + 1 if TASKS else 1  # Assign ID safely
            TASKS.append(task)
            return jsonify(TASKS), 201 # Created
        else:
            abort(400, description="Invalid task data")


if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

